package me.minis.ledger;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class SummaryNotice extends BroadcastReceiver {
 private static final int ID=2301;private static final String CHANNEL="ledger_summary";private static final ScheduledThreadPoolExecutor worker=new ScheduledThreadPoolExecutor(1);private static ScheduledFuture<?> pending;private static String lastSignature="",lastDay="";static{worker.setRemoveOnCancelPolicy(true);}
 public static synchronized void checkDate(Context c){String day=start(System.currentTimeMillis(),0)+"|"+TimeZone.getDefault().getID();if(!day.equals(lastDay)){lastDay=day;changed(c);}}
 public static synchronized void changed(Context c){PowerDetail.count("summary_request");Context app=c.getApplicationContext();if(pending!=null)pending.cancel(false);pending=worker.schedule(()->update(app),300,TimeUnit.MILLISECONDS);}
 public static long start(long now,int mode){Calendar d=Calendar.getInstance();d.setTimeInMillis(now);d.set(Calendar.HOUR_OF_DAY,0);d.set(Calendar.MINUTE,0);d.set(Calendar.SECOND,0);d.set(Calendar.MILLISECOND,0);if(mode==1)d.add(Calendar.DAY_OF_MONTH,-(d.get(Calendar.DAY_OF_WEEK)+5)%7);if(mode==2)d.set(Calendar.DAY_OF_MONTH,1);return d.getTimeInMillis();}
 public static long[] totals(JSONArray rows,long now,boolean net)throws Exception{long[] out=new long[3];long[] starts={start(now,0),start(now,1),start(now,2)};Calendar tomorrow=Calendar.getInstance();tomorrow.setTimeInMillis(starts[0]);tomorrow.add(Calendar.DAY_OF_MONTH,1);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(!r.optString("status").equals("confirmed")||r.optInt("excluded",0)!=0)continue;long t=r.getLong("time");if(t>=tomorrow.getTimeInMillis())continue;String kind=r.getString("kind");long value=kind.equals("expense")?r.getLong("cents"):net&&kind.equals("income")?-r.getLong("cents"):0;for(int j=0;j<3;j++)if(t>=starts[j])out[j]+=value;}return out;}
 private static PendingIntent action(Context c,String a,int id){Intent i=new Intent(c,SummaryNotice.class).setAction(a);return PendingIntent.getBroadcast(c,id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static int getNoticeIcon(Context c){int id=c.getResources().getIdentifier("ic_notice_book","drawable",c.getPackageName());return id!=0?id:android.R.drawable.ic_menu_agenda;}
 private static String money(long c){return String.format(Locale.CHINA,"%.2f",c/100.0);}
 public static synchronized void update(Context c){try(PowerDetail.Span span=PowerDetail.span("summary")){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(!LedgerDb.prefs(c).getBoolean("summary_on",true)){nm.cancel(ID);lastSignature="";return;}
 NotificationChannel ch=new NotificationChannel(CHANNEL,"消费汇总（静默常驻）",NotificationManager.IMPORTANCE_LOW);ch.setSound(null,null);ch.enableVibration(false);ch.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);nm.createNotificationChannel(ch);
 boolean net=LedgerDb.prefs(c).getBoolean("summary_net",false);long[] totals;BudgetUsage budget;long now=System.currentTimeMillis();try(LedgerDb db=new LedgerDb(c)){totals=db.summaryTotals(now,net);budget=BudgetUsage.read(c,db,now);}boolean dark=(c.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES;
 String signature=net+"|"+Arrays.toString(totals)+"|"+budget.limit+"|"+budget.used+"|"+budget.month+"|"+budget.style+"|"+dark;if(signature.equals(lastSignature)){for(android.service.notification.StatusBarNotification n:nm.getActiveNotifications())if(n.getId()==ID){PowerDetail.count("summary_skip");return;}}
 String line="日 ¥"+money(totals[0])+"  ·  周 ¥"+money(totals[1])+"  ·  月 ¥"+money(totals[2]);String title=net?"消费汇总 · 净花销":"消费汇总 · 纯支出";
 Notification.Builder b=new Notification.Builder(c,CHANNEL).setSmallIcon(getNoticeIcon(c)).setColor(0xff626ddd).setContentTitle(title).setContentText(line).setStyle(new Notification.BigTextStyle().bigText("今日  ¥"+money(totals[0])+"\n本周  ¥"+money(totals[1])+"\n本月  ¥"+money(totals[2]))).setContentIntent(PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).setOngoing(true).setOnlyAlertOnce(true).setVisibility(Notification.VISIBILITY_PRIVATE).setShowWhen(false).addAction(new Notification.Action.Builder(null,net?"切换纯支出":"切换净花销",action(c,"toggle",1)).build()).addAction(new Notification.Action.Builder(null,"刷新",action(c,"refresh",2)).build());if(budget.visible()){android.widget.RemoteViews v=new android.widget.RemoteViews(c.getPackageName(),c.getResources().getIdentifier("summary_native","layout",c.getPackageName()));int t=c.getResources().getIdentifier("summary_title","id",c.getPackageName()),rows=c.getResources().getIdentifier("summary_totals","id",c.getPackageName()),graphic=c.getResources().getIdentifier("summary_budget","id",c.getPackageName());v.setTextViewText(t,title);v.setTextViewText(rows,"今日  ¥"+money(totals[0])+"\n本周  ¥"+money(totals[1])+"\n本月  ¥"+money(totals[2]));BudgetNative.bind(c,v,"summary_budget",budget,dark);v.setOnClickPendingIntent(graphic,action(c,"budget_noop",340));b.setStyle(new Notification.DecoratedCustomViewStyle()).setCustomBigContentView(v);}nm.notify(ID,b.build());PowerDetail.count("summary_notify");lastSignature=signature;
 }catch(Exception e){LedgerDb.prefs(c).edit().putString("summary_error","汇总通知更新失败，请检查通知权限").apply();}}
 public void onReceive(Context c,Intent i){if("budget_noop".equals(i.getAction()))return;if("toggle".equals(i.getAction())){android.content.SharedPreferences p=LedgerDb.prefs(c);p.edit().putBoolean("summary_net",!p.getBoolean("summary_net",false)).apply();}final PendingResult r=goAsync();worker.execute(()->{try{update(c);}finally{r.finish();}});}
}
